olorScheme.background),        contentPadding = androidx.compose.foundation.layout.PaddingValues(16.dp),        verticalArrangement = Arrangement.spacedBy(16.dp),    ) {        item {            Text(                text = "Memory Browser",                style = MaterialTheme.typography.headlineLarge,                fontWeight = FontWeight.Bold,                color = MaterialTheme.colorScheme.onBackground,            )        }        // Stats        item {            Row(                modifier = Modifier.fillMaxWidth(),                horizontalArrangement = Arrangement.spacedBy(8.dp),            ) {                StatChip(label = "Total", value = "$totalCount")                StatChip(label = "Episodic", value = "$episodic")                StatChip(label = "Semantic", value = "$semantic")                StatChip(label = "Storage", value = "%.2f MB".format(storageMb))            }        }        // Recent memories        item {            GlassPanel(title = "Recent Memories (${recent.size})") {                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                    if (recent.isEmpty()) {                        Text(                            text = "No memories yet. As you interact with NOUS, it will remember important facts and events here.",                            style = MaterialTheme.typography.bodyMedium,                            color = MaterialTheme.colorScheme.onSurfaceVariant,                        )                    } else {                        recent.forEach { mem ->                            Column(                                modifier = Modifier                                    .fillMaxWidth()                                    .background(                                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),                                        shape = RoundedCornerShape(12.dp),                                    )                                    .padding(12.dp),                            ) {                                Text(                                    text = mem.timestamp,                                    style = MaterialTheme.typography.labelSmall,                                    color = MaterialTheme.colorScheme.onSurfaceVariant,                                )                                Text(                                    text = mem.content,                                    style = MaterialTheme.typography.bodyMedium,                                    color = MaterialTheme.colorScheme.onSurface,                                )                                Text(                                    text = "Importance: ${(mem.importance * 100).toInt()}% · Type: ${mem.type}",                                    style = MaterialTheme.typography.labelSmall,                                    color = MaterialTheme.colorScheme.onSurfaceVariant,                                )                            }                        }                    }                }            }        }        // Known facts        item {            GlassPanel(title = "Known Facts (${facts.size})") {                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {                    if (facts.isEmpty()) {                        Text(                            text = "NOUS hasn't learned any facts about you yet.",                            style = MaterialTheme.typography.bodyMedium,                            color = MaterialTheme.colorScheme.onSurfaceVariant,                        )                    } else {                        facts.forEach { fact ->                            Text(                                text = "• $fact",                                style = MaterialTheme.typography.bodyMedium,                                color = MaterialTheme.colorScheme.onSurface,                            )                        }                    }                }            }        }    }}